async function noawait(): Promise<number> { return 1; }
function main(): void {
  const m = new Map<string, any>();
  m.set("a", async () => 3);
  console.log(m);
  const s = new Set<any>();
  s.add(() => 1);
  console.log(s);
  const n = new Map<string, any>();
  n.set("n", async function named() { await 0; return 1; });
  console.log(n);
  const p = new Map<string, any>();
  p.set("p", noawait);
  console.log(p);
  const q = new Map<string, any>();
  q.set("q", (x: number) => x + 1);
  console.log(q);
}
